#pragma once

#include <cstddef>
#include <string>
#include <vector>

namespace ai::navvis {

struct Point {
   unsigned id {};
   float x {}, y {}, z {};
   int source {};
   bool standing {}, crouching {}, isolated {};
};

struct Edge {
   unsigned from {}, to {};
   int type {};
};

struct Data {
   std::string map;
   std::string sha256;
   std::vector <Point> points;
   std::vector <Edge> edges;
};

// Input is generated by the independent Map Tool, never by the YaPB graph editor.
bool load (const char *filename, const char *expectedMap, Data &out);
void frame (edict_t *editor);
void toggle (edict_t *editor, int option);
void radius (float value);
float radius ();
void reset ();

} // namespace ai::navvis
